span id="partnerColorSummaryValue">{{ $accent }}</span></span><i class="bi bi-chevron-down profile-collapse-chevron"></i></summary><fieldset class="profile-fieldset"><legend class="visually-hidden">Couleur dominante</legend><div class="ds-color-grid profile-color-grid" id="partnerAccentSwatches">@foreach(['#7C5CFC','#20BFA9','#3B82F6','#FF9F43','#E94F86','#62A744'] as $color)<button type="button" class="ds-color-swatch {{ $accent === $color ? 'is-selected' : '' }}" style="--swatch:{{ $color }}" data-accent="{{ $color }}" aria-label="Choisir la couleur {{ $color }}" aria-pressed="{{ $accent === $color ? 'true' : 'false' }}"></button>@endforeach</div><div class="profile-accent-row"><div class="profile-field"><label for="partnerAccentText">Couleur personnalisée</label><div class="profile-color-control"><input type="color" id="partnerAccentPicker" value="{{ $accent }}"><input type="text" id="partnerAccentText" name="accent_color" value="{{ $accent }}" maxlength="7" pattern="#[0-9A-Fa-f]{6}" required></div></div><div class="profile-theme-preview"><div><strong>Aperçu du thème</strong><small id="partnerContrastStatus">Contraste calculé automatiquement.</small></div><button type="button" class="saas-primary-action" tabindex="-1">Action principale</button></div></div></fieldset></details><div class="profile-form-actions profile-form-actions-split"><button type="button" class="profile-secondary-button" id="partnerResetAppearance"><i class="bi bi-arrow-counterclockwise"></i>Couleur par défaut</button><button type="submit" class="saas-primary-action" data-loading-text="Enregistrement…"><i class="bi bi-check2-circle"></i>Enregistrer mon apparence</button></div></form></div>
