<script>document.addEventListener('DOMContentLoaded',()=>{const t=[...document.querySelectorAll('[data-profile-tab]')],p=[...document.querySelectorAll('[data-profile-panel]'),];const a=n=>{t.forEach(x=>{let y=x.dataset.profileTab===n;x.classList.toggle('is-active',y);x.setAttribute('aria-selected',y)});p.forEach(x=>x.hidden=x.dataset.profilePanel!==n);history.replaceState(null,'',`#${n}`)};t.forEach(x=>x.onclick=()=>a(x.dataset.profileTab));if(['identity','security','appearance'].includes(location.hash.slice(1)))a(location.hash.slice(1));document.querySelectorAll('[data-password-toggle]').forEach(b=>b.onclick=()=>{let i=document.getElementById(b.dataset.passwordToggle),v=i.type==='text';i.type=v?'password':'text';b.querySelector('i').className=`bi ${v?'bi-eye':'bi-eye-slash'}`});const f=document.getElementById('partnerAppearanceForm'),text=document.getElementById('partnerAccentText'),pick=document.getElementById('partnerAccentPicker');if(!f||!window.DesignSystem)return;const preview=v=>{v=window.DesignSystem.normaliseHex(v);text.value=pick.value=v;window.DesignSystem.apply({mode:f.querySelector('input[name=appearance_mode]:checked').value,accent:v});document.getElementById('partnerColorSummary').style.setProperty('--summary-color',v);document.getElementById('partnerColorSummaryValue').textContent=v};f.querySelectorAll('input[name=appearance_mode]').forEach(i=>i.onchange=()=>{document.getElementById('partnerModeSummary').textContent=i.dataset.modeLabel;preview(text.value)});f.querySelectorAll('[data-accent]').forEach(x=>x.onclick=()=>preview(x.dataset.accent));pick.oninput=()=>preview(pick.value);text.onchange=()=>preview(text.value);document.getElementById('partnerResetAppearance').onclick=()=>preview('#3B82F6');preview(text.value)});</script>
